class Counter:
    def __init__(self):
        self._value = 0
        self._alive = True

    def increment(self):
        """Increment the counter by 1 if the counter is alive."""
        if self._alive:
            self._value += 1

    def decrement(self):
        """Decrement the counter by 1 if alive and value > 0."""
        if self._alive and self._value > 0:
            self._value -= 1

    def get_value(self):
        """Return the current value of the counter."""
        return self._value

    def is_alive(self):
        """Return True if the counter is alive, False otherwise."""
        return self._alive

    def close(self):
        """Set the counter's state to inactive."""
        self._alive = False
